    (SELECT subject_id FROM ordering.delay_alert WHERE id = md5('qa35:a1')::uuid) = md5('qa35:po1')::uuid);
SELECT pg_temp.expect_fail('DA13 a second open AT_RISK on it', $q$
    INSERT INTO ordering.delay_alert (id, type, production_order_id, sales_order_id, opened_at)
    VALUES (gen_random_uuid(), 'AT_RISK', md5('qa35:po1')::uuid, md5('qa35:order')::uuid, NOW()) $q$);
SELECT pg_temp.expect_ok('DA13a the recompute''s insert of a second one is let through and writes nothing', $q$
    INSERT INTO ordering.delay_alert (id, type, production_order_id, sales_order_id, opened_at)
    VALUES (gen_random_uuid(), 'AT_RISK', md5('qa35:po1')::uuid, md5('qa35:order')::uuid, NOW())
    ON CONFLICT (type, subject_id) WHERE closed_at IS NULL DO NOTHING $q$);
SELECT pg_temp.expect_true('DA13b still one open AT_RISK on it',
    (SELECT count(*) FROM ordering.delay_alert WHERE type = 'AT_RISK' AND production_order_id = md5('qa35:po1')::uuid
        AND closed_at IS NULL) = 1);
SELECT pg_temp.expect_fail('DA14 closed before it was opened', $q$
    UPDATE ordering.delay_alert SET closed_at = opened_at - INTERVAL '1 minute' WHERE id = md5('qa35:a1')::uuid $q$);
SELECT pg_temp.expect_fail('DA15 moved to another subject', $q$
    UPDATE ordering.delay_alert SET type = 'PRODUCTION_LATE' WHERE id = md5('qa35:a1')::uuid $q$);
SELECT pg_temp.expect_fail('DA15a its opening rewritten', $q$
    UPDATE ordering.delay_alert SET opened_at = opened_at - INTERVAL '1 day' WHERE id = md5('qa35:a1')::uuid $q$);
SELECT pg_temp.expect_ok('DA16 AT_RISK closed, then the condition holds again: a new alert', $q$
    UPDATE ordering.delay_alert SET closed_at = NOW() WHERE id = md5('qa35:a1')::uuid;
    INSERT INTO ordering.delay_alert (id, type, production_order_id, sales_order_id, opened_at)
    VALUES (md5('qa35:a3')::uuid, 'AT_RISK', md5('qa35:po1')::uuid, md5('qa35:order')::uuid, NOW()) $q$);
SELECT pg_temp.expect_fail('DA17 a closed alert reopened', $q$
    UPDATE ordering.delay_alert SET closed_at = NULL WHERE id = md5('qa35:a1')::uuid $q$);
SELECT pg_temp.expect_fail('DA17a a closed alert''s close rewritten', $q$
    UPDATE ordering.delay_alert SET closed_at = closed_at + INTERVAL '1 hour' WHERE id = md5('qa35:a1')::uuid $q$);
SELECT pg_temp.expect_ok('DA18 PO_NEEDED and DELIVERY_LATE open on batch 1', $q$
    INSERT INTO ordering.delay_alert (id, type, delivery_batch_id, sales_order_id, opened_at)
    VALUES (md5('qa35:a4')::uuid, 'PO_NEEDED', md5('qa35:b1')::uuid, md5('qa35:order')::uuid, NOW()),
           (md5('qa35:a5')::uuid, 'DELIVERY_LATE', md5('qa35:b1')::uuid, md5('qa35:order')::uuid, NOW()) $q$);
SELECT pg_temp.expect_fail('DA19 a second open DELIVERY_LATE on batch 1', $q$
    INSERT INTO ordering.delay_alert (id, type, delivery_batch_id, sales_order_id, opened_at)
    VALUES (gen_random_uuid(), 'DELIVERY_LATE', md5('qa35:b1')::uuid, md5('qa35:order')::uuid, NOW()) $q$);
SELECT pg_temp.expect_ok('DA20 DELIVERY_LATE on batch 2 beside batch 1''s', $q$
    INSERT INTO ordering.delay_alert (id, type, delivery_batch_id, sales_order_id, opened_at)
    VALUES (gen_random_uuid(), 'DELIVERY_LATE', md5('qa35:b2')::uuid, md5('qa35:order')::uuid, NOW()) $q$);
SELECT pg_temp.expect_true('DA21 the open ones: AT_RISK (new), PRODUCTION_LATE, PO_NEEDED, two DELIVERY_LATE',
    (SELECT count(*) FROM ordering.delay_alert WHERE sales_order_id = md5('qa35:order')::uuid
        AND closed_at IS NULL) = 5);

\echo '--- who reads the schedule and the flags, who is told (BR-30, cleanup P8)'
CREATE FUNCTION pg_temp.grants(role_code TEXT, permission_code TEXT) RETURNS BOOLEAN LANGUAGE sql AS $$
    SELECT EXISTS (SELECT 1 FROM identity.role_permission rp
                     JOIN identity.app_role r ON r.id = rp.role_id
                     JOIN identity.permission p ON p.id = rp.permission_id
                    WHERE r.code = role_code AND p.code = permission_code)
$$;
SELECT pg_temp.expect_true('DA22 the schedule: the coordinator, Sales, the Sales Manager, the warehouse manager',
    pg_temp.grants('PRODUCTION_COORDINATOR', 'production-schedule:READ')
    AND pg_temp.grants('PRODUCTION_COORDINATOR', 'production-schedule:VIEW_PAGE')
    AND pg_temp.grants('SALES_STAFF', 'production-schedule:READ')
    AND pg_temp.grants('SALES_MANAGER', 'production-schedule:READ')
    AND pg_temp.grants('WAREHOUSE_MANAGER', 'production-schedule:READ')
    AND NOT pg_temp.grants('WAREHOUSE_STAFF', 'production-schedule:READ')
    AND NOT pg_temp.grants('CUSTOMER', 'production-schedule:READ'));
SELECT pg_temp.expect_true('DA23 the delay flags (and DELIVERY_LATE): Sales, the Sales Manager, the warehouse manager',
    pg_temp.grants('SALES_STAFF', 'delay-alerts:READ')
    AND pg_temp.grants('SALES_MANAGER', 'delay-alerts:READ')
    AND pg_temp.grants('WAREHOUSE_MANAGER', 'delay-alerts:READ')
    AND NOT pg_temp.grants('PRODUCTION_COORDINATOR', 'delay-alerts:READ')
    AND NOT pg_temp.grants('CUSTOMER', 'delay-alerts:READ'));
SELECT pg_temp.expect_true('DA24 the warehouse manager is the only warehouse-bound reader of the schedule',
    (SELECT array_agg(r.code ORDER BY r.code) FROM identity.role_permission rp
       JOIN identity.app_role r ON r.id = rp.role_id JOIN identity.permission p ON p.id = rp.permission_id
      WHERE p.code = 'production-schedule:READ' AND r.data_scope <> 'ALL') = ARRAY['WAREHOUSE_MANAGER']::varchar[]);

ROLLBACK;
